export function WordCount({
  text = "{{text}}",
  wordCount = {{wordCount}},
  limit = {{limit}},
  nearLimit = {{nearLimit}},
  countMode = "{{countMode}}",
  accent = "{{accent}}",
}) {
  const warnColor = "#b3431f";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, maxWidth: 320, border: "1.5px solid #24143020", borderRadius: 10 }}>
      <div contentEditable suppressContentEditableWarning role="textbox" aria-multiline="true" aria-label="Message" aria-describedby="wcd-react-counter"
        style={{ minHeight: "3.4em", fontSize: 14, lineHeight: 1.6, paddingBottom: 10, borderBottom: "1px solid #24143014", marginBottom: 8 }}>
        {text}
      </div>
      <p id="wcd-react-counter" role="status" style={{ margin: 0, fontSize: 12, color: nearLimit ? warnColor : "#241430aa", display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{ fontWeight: 700, color: nearLimit ? warnColor : accent }}>{wordCount}</span> / {limit} {countMode}
        {nearLimit && <span style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".03em" }}>Approaching limit</span>}
      </p>
    </div>
  );
}
